bool FiniteTransform(const JointTransform3D& v){const float a[]={v.translation.x,v.translation.y,v.translation.z,v.rotation.x,v.rotation.y,v.rotation.z,v.scale.x,v.scale.y,v.scale.z,v.quaternion.x,v.quaternion.y,v.quaternion.z,v.quaternion.w};return std::all_of(std::begin(a),std::end(a),[](float x){return std::isfinite(x);})&&v.scale.x!=0&&v.scale.y!=0&&v.scale.z!=0;}
bool FiniteMatrix(const Matrix4& m){for(size_t r=0;r<4;++r)for(size_t c=0;c<4;++c)if(!std::isfinite(m[r][c]))return false;return true;}
size_t PoseBytes(const AnimationPose3D& p){return p.localTransforms.capacity()*sizeof(JointTransform3D)+p.globalMatrices.capacity()*sizeof(Matrix4);}
size_t ClipBytes(const AnimationClip3D& clip){size_t bytes=clip.tracks.capacity()*sizeof(AnimationTrack3D);for(const auto& track:clip.tracks)bytes+=track.keyframes.capacity()*sizeof(AnimationKeyframe3D);return bytes;}
