bool AnimationGraph3D::SetState(size_t state,float duration,bool sync){if(state>=stateCount_||!std::isfinite(duration)||duration<0)return false;if(state==state_&&!transitioning_)return true;if(rootMotionPrepared_&&!BeginRootMotionTransition(state,duration,sync))return false;transitionSnapshotValid_=baseScratch_.localTransforms.size()==jointCount_;if(transitionSnapshotValid_)transitionFrom_=baseScratch_;if(transitioning_)++stats_.interruptions;if(!sync)phase_=0;state_=state;transitionDuration_=duration;transitionElapsed_=0;transitioning_=duration>0&&transitionSnapshotValid_;++stats_.transitions;return true;}
