bool AnimationGraph3D::CanCommitRootMotionPreview(const AnimationGraphRootMotionPreviewToken3D& token,const AnimationPose3D& pose)const noexcept{return rootPreviewPending_&&pose.localTransforms.size()==jointCount_&&pose.globalMatrices.size()==jointCount_&&token.valid&&token.owner==reinterpret_cast<std::uintptr_t>(this)&&token.pose==&pose&&token.generation==rootGeneration_&&token.serial==rootPreviewSerial_&&token.tick==rootPreviewResult_.delta.tick&&token.baseStateHash==rootPreviewBaseStateHash_&&token.poseHash==PoseHash(pose)&&token.candidateHash==rootPreviewResult_.deterministicHash;}
void AnimationGraph3D::CommitRootMotionPreviewUnchecked(AnimationGraphRootMotionPreviewToken3D& token,AnimationPose3D& pose)noexcept{for(std::size_t i=0;i<jointCount_;++i){pose.localTransforms[i]=rootCandidatePose_.localTransforms[i];pose.globalMatrices[i]=rootCandidatePose_.globalMatrices[i];}rootLeaves_=rootCandidateLeaves_;rootLeafCount_=rootCandidateLeafCount_;rootTransitionElapsed_=rootCandidateTransitionElapsed_;if(rootTransitionDuration_>0&&rootTransitionElapsed_>=rootTransitionDuration_){std::size_t write{};for(std::size_t i=0;i<rootLeafCount_;++i)if(rootLeaves_[i].weightEnd>0){auto leaf=rootLeaves_[i];leaf.weightStart=leaf.weightEnd;rootLeaves_[write++]=leaf;}rootLeafCount_=write;rootTransitionDuration_=rootTransitionElapsed_=0;}rootLastTick_=rootPreviewResult_.delta.tick;rootAnchored_=true;rootPreviewPending_=false;++rootGeneration_;token={};}
bool AnimationGraph3D::CommitRootMotionPreview(AnimationGraphRootMotionPreviewToken3D& token,AnimationPose3D& pose,AnimationGraphRootMotionResult3D* output)noexcept{if(!CanCommitRootMotionPreview(token,pose)){CancelRootMotionPreview(token);return false;}const auto result=rootPreviewResult_;CommitRootMotionPreviewUnchecked(token,pose);if(output)*output=result;return true;}
bool AnimationGraph3D::CancelRootMotionPreview(AnimationGraphRootMotionPreviewToken3D& token)noexcept{if(!rootPreviewPending_||!token.valid||token.owner!=reinterpret_cast<std::uintptr_t>(this)||token.serial!=rootPreviewSerial_)return false;rootPreviewPending_=false;token={};return true;}
bool AnimationGraph3D::EvaluateRootMotionTick(const Skeleton3D& skeleton,SkeletonCompatibilityId3D expected,AnimationGraphRootMotionTick3D tick,AnimationPose3D& pose,AnimationGraphRootMotionResult3D* output)noexcept{InvalidateRootMotionPreview(false);AnimationGraphRootMotionPreviewToken3D token{};AnimationGraphRootMotionResult3D result{};if(!PreviewRootMotionTick(skeleton,expected,tick,pose,token,&result)||!CommitRootMotionPreview(token,pose,nullptr))return false;if(output)*output=result;return true;}
void AnimationGraph3D::ResetRootMotion()noexcept{InvalidateRootMotionPreview(true);rootLastTick_=0;rootAnchored_=false;rootTransitionElapsed_=0;for(std::size_t i=0;i<rootLeafCount_;++i)rootLeaves_[i].clockQ32=0;}
bool AnimationGraph3D::CanResetRootMotion()const noexcept{return rootMotionPrepared_&&rootGeneration_!=(std::numeric_limits<std::uint64_t>::max)();}
bool AnimationGraph3D::CanTeleportRootMotion(std::uint64_t previousTick)const noexcept{return CanResetRootMotion()&&previousTick!=(std::numeric_limits<std::uint64_t>::max)();}
bool AnimationGraph3D::TeleportRootMotion(std::uint64_t previousTick)noexcept{if(!CanTeleportRootMotion(previousTick))return false;InvalidateRootMotionPreview(true);rootLastTick_=previousTick;rootAnchored_=false;return true;}
